54:         {
55:             return Err(JournalError::PayloadDigestMismatch);
56:         }
57:         Ok(())
58:     }
59: 
60:     fn validate_policy(&self, policy: RuntimePolicy) -> Result<(), JournalError> {
61:         if !matches!(
62:             policy,
63:             RuntimePolicy::Relaxed | RuntimePolicy::Journaled | RuntimePolicy::Strict
64:         ) {
65:             return Err(JournalError::AdmissionRequired);
66:         }
67:         if !self.artifact.required_capabilities.is_empty() {
68:             return Err(JournalError::CapabilityDenied);
69:         }
70:         crate::admission::verify_accepted_artifact_for_policy(&self.artifact, policy)?;
71:         Ok(())
72:     }
